DASHBOARD_HTML = r'''<!doctype html>
<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veloikos Trading</title>
<style>
:root{--bg:#070a0b;--panel:#0d1214;--panel2:#11181a;--line:#263134;--text:#eef2f0;--muted:#93a09d;--green:#20c985;--red:#fa6875;--gold:#d7b66a;--blue:#61a8ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}header{height:62px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-bottom:1px solid var(--line);background:#090d0e}.brand{font:700 24px Georgia,serif;letter-spacing:-.5px}.brand span{font:700 10px Inter,sans-serif;letter-spacing:2.3px;color:var(--gold);margin-left:8px}.status{font-size:11px;color:var(--green);border:1px solid #21513d;background:#0c1b15;padding:7px 10px;border-radius:4px}.layout{display:grid;grid-template-columns:205px minmax(620px,1fr) 280px;min-height:calc(100vh - 62px)}aside{border-right:1px solid var(--line);background:#0a0e0f;padding:16px 10px}.right{border-right:0;border-left:1px solid var(--line);padding:16px}.label{font-size:10px;letter-spacing:1.3px;color:var(--muted);text-transform:uppercase}.watch{width:100%;padding:12px 9px;text-align:left;background:transparent;border:0;border-bottom:1px solid #1e282b;color:var(--text);cursor:pointer}.watch:hover,.watch.selected{background:#14201d;border-left:2px solid var(--gold)}.watch b{display:block;font-size:14px}.watch span{display:block;color:var(--muted);font-size:11px;margin-top:3px}main{padding:16px;min-width:0}.instrument{display:flex;align-items:flex-end;gap:22px;padding:0 3px 14px;border-bottom:1px solid var(--line)}.symbol{font-size:34px;font-weight:800;line-height:1}.market-title{font-size:19px;font-weight:700}.connected{color:var(--green);font-size:11px;margin-top:4px}.quote-grid{margin-left:auto;display:grid;grid-template-columns:repeat(4,minmax(70px,1fr));gap:19px}.quote-grid b{display:block;font-size:16px;margin-top:5px}.up{color:var(--green)}.down{color:var(--red)}.chart-panel{height:440px;margin-top:14px;background:var(--panel);border:1px solid var(--line);position:relative;overflow:hidden}.chart-top{height:44px;display:flex;align-items:center;justify-content:space-between;padding:0 14px;border-bottom:1px solid var(--line)}.chart-top b{font-size:13px}.chart-note{font-size:11px;color:var(--muted)}#chart{width:100%;height:calc(100% - 44px);display:block}.empty{height:100%;display:grid;place-items:center;color:var(--muted);font-size:13px}.bottom{display:grid;grid-template-columns:1fr 1.35fr;gap:14px;margin-top:14px}.panel{border:1px solid var(--line);background:var(--panel);min-height:185px}.panel h2{font-size:13px;margin:0;padding:13px 14px;border-bottom:1px solid var(--line)}.content{padding:0 14px}.list-row{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8px;padding:11px 0;border-bottom:1px solid #20292c}.list-row:last-child{border-bottom:0}.secondary{color:var(--muted);font-size:11px;margin-top:3px}.event{display:grid;grid-template-columns:8px 1fr auto;gap:9px;align-items:start;padding:10px 0;border-bottom:1px solid #20292c}.dot{width:7px;height:7px;border-radius:50%;background:var(--gold);margin-top:5px}.event-title{font-weight:600;font-size:12px}.event-time{font-size:11px;color:var(--muted);white-space:nowrap}.account-grid{display:grid;grid-template-columns:1fr 1fr;margin-top:12px;border:1px solid var(--line)}.metric{padding:13px 10px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.metric:nth-child(2n){border-right:0}.metric:nth-last-child(-n+2){border-bottom:0}.metric b{display:block;font-size:18px;margin-top:5px}.state{margin-top:16px;border:1px solid var(--line);padding:13px;background:var(--panel)}.state b{display:block;margin:6px 0}.state p{margin:0;color:var(--muted);font-size:12px;line-height:1.45}.refresh{color:var(--muted);font-size:11px;margin-top:13px}@media(max-width:1050px){.layout{grid-template-columns:185px 1fr}.right{display:none}}@media(max-width:760px){header{padding:0 13px}.layout{display:block}aside{display:none}main{padding:10px}.quote-grid{display:none}.chart-panel{height:350px}.bottom{grid-template-columns:1fr}.brand{font-size:21px}}
</style></head>
<body><header><div class="brand">Veloikos <span>TRADING</span></div><div class="status">LIVE EXECUTION ACTIVE</div></header>
<div class="layout"><aside><div class="label">Watchlist</div><div id="watch"></div><div class="refresh">Select a symbol to load its live quote and daily chart.</div></aside>
<main><section class="instrument"><div><div class="label">Selected instrument</div><div id="symbol" class="symbol">SPY</div></div><div><div id="marketTitle" class="market-title">Live market</div><div id="feedState" class="connected">Loading broker data</div></div><div class="quote-grid"><div><div class="label">Last</div><b id="last">--</b></div><div><div class="label">Bid</div><b id="bid">--</b></div><div><div class="label">Ask</div><b id="ask">--</b></div><div><div class="label">Spread</div><b id="spread">--</b></div></div></section>
<section class="chart-panel"><div class="chart-top"><b id="chartName">SPY daily candles</b><span id="chartNote" class="chart-note">Loading 45 trading days</span></div><svg id="chart" viewBox="0 0 1000 390" preserveAspectRatio="none"></svg></section>
<div class="bottom"><section class="panel"><h2>Open live positions</h2><div id="positions" class="content"><div class="list-row">Loading positions</div></div></section><section class="panel"><h2>Execution activity</h2><div id="activity" class="content"><div class="event"><i class="dot"></i><div class="event-title">Loading activity</div></div></div></section></div></main>
<aside class="right"><div class="label">Live account</div><div class="account-grid"><div class="metric"><span class="label">Equity</span><b id="equity">$--</b></div><div class="metric"><span class="label">Cash</span><b id="cash">$--</b></div><div class="metric"><span class="label">Buying power</span><b id="buyingPower">$--</b></div><div class="metric"><span class="label">Positions</span><b id="positionCount">0</b></div></div><section class="state"><div class="label">Live worker</div><b id="workerState">Checking strategy</b><p id="workerDetail">The worker evaluates the validated trend-pullback rules every minute. It does not submit an order unless the full signal and risk checks pass.</p></section><section class="state"><div class="label">Market status</div><b id="marketState">--</b><p>Account figures update from the broker. Chart and quote use the selected symbol only, keeping API use within the broker rate limit.</p></section></aside></div>
<script>
const syms=['SPY','QQQ','IWM','NVDA','AAPL','MSFT','GLD','TLT'];let selected='SPY';
const q=s=>document.querySelector(s), money=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD'}), esc=s=>String(s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function watch(){q('#watch').innerHTML=syms.map(s=>'<button class="watch '+(s===selected?'selected':'')+'" data-symbol="'+s+'"><b>'+s+'</b><span>'+ (s===selected?'Selected':'Load quote and chart')+'</span></button>').join('');document.querySelectorAll('.watch').forEach(b=>b.onclick=()=>{selected=b.dataset.symbol;watch();loadMarket();});}
function candles(bars){const svg=q('#chart');if(!bars||!bars.length){svg.innerHTML='<text x="500" y="195" text-anchor="middle" fill="#93a09d" font-size="15">Market data unavailable for this symbol</text>';return}const w=1000,h=390,p=26,lo=Math.min(...bars.map(x=>Number(x.low))),hi=Math.max(...bars.map(x=>Number(x.high))),span=Math.max(hi-lo,.01),y=v=>h-p-(v-lo)/span*(h-2*p),step=(w-2*p)/bars.length,bw=Math.max(3,step*.58);let out='';for(let i=0;i<5;i++){let yy=p+i*(h-2*p)/4;out+='<line x1="'+p+'" x2="'+(w-p)+'" y1="'+yy+'" y2="'+yy+'" stroke="#263134" stroke-width="1"/>'}bars.forEach((b,i)=>{let x=p+i*step+step/2,up=Number(b.close)>=Number(b.open),c=up?'#20c985':'#fa6875',top=y(Math.max(Number(b.open),Number(b.close))),bh=Math.max(2,Math.abs(y(Number(b.open))-y(Number(b.close))));out+='<line x1="'+x+'" x2="'+x+'" y1="'+y(Number(b.high))+'" y2="'+y(Number(b.low))+'" stroke="'+c+'" stroke-width="1.4"/><rect x="'+(x-bw/2)+'" y="'+top+'" width="'+bw+'" height="'+bh+'" fill="'+c+'"/>';});out+='<text x="'+p+'" y="16" fill="#93a09d" font-size="11">'+hi.toFixed(2)+'</text><text x="'+p+'" y="'+(h-8)+'" fill="#93a09d" font-size="11">'+lo.toFixed(2)+'</text>';svg.innerHTML=out;}
async function loadMarket(){q('#symbol').textContent=selected;q('#chartName').textContent=selected+' daily candles';q('#feedState').textContent='Loading selected symbol';try{let d=await fetch('/terminal/market?symbol='+encodeURIComponent(selected)).then(r=>r.ok?r.json():Promise.reject());let z=d.quote||{},last=Number(z.last||0),bid=Number(z.bid||0),ask=Number(z.ask||0),sp=ask&&bid?(ask-bid):0;q('#last').textContent=last?money(last):'--';q('#bid').textContent=bid?money(bid):'--';q('#ask').textContent=ask?money(ask):'--';q('#spread').textContent=sp?money(sp):'--';q('#feedState').textContent=last?'Broker quote loaded':'No current quote';q('#chartNote').textContent=(d.bars||[]).length+' daily bars';candles(d.bars||[])}catch(e){q('#feedState').textContent='Market data temporarily unavailable';q('#chartNote').textContent='Retrying automatically';candles([])}}
function fmtEvent(t){return String(t||'activity').replace(/^alpaca_live_worker_/,'Worker: ').replace(/^alpaca_live_/,'Live: ').replaceAll('_',' ')}function eventDetail(e){if(e.payload&&e.payload.reasons&&e.payload.reasons.length)return e.payload.reasons.join(', ');return e.payload&&e.payload.strategy?e.payload.strategy:'Live execution audit record'}
async function loadAccount(){try{let[d,a]=await Promise.all([fetch('/brokers/alpaca/live-portfolio').then(r=>r.ok?r.json():Promise.reject()),fetch('/live/activity?limit=8').then(r=>r.ok?r.json():Promise.reject())]),b=d.balances||{},p=d.positions||[],events=a.events||[];q('#equity').textContent=money(b.equity);q('#cash').textContent=money(b.cash);q('#buyingPower').textContent=money(b.buying_power);q('#positionCount').textContent=p.length;q('#marketState').textContent=d.market_clock&&d.market_clock.is_open?'US market open':'US market closed';q('#positions').innerHTML=p.length?p.map(x=>'<div class="list-row"><div><b>'+esc(x.symbol)+'</b><div class="secondary">'+esc(x.qty)+' shares at '+money(x.avg_entry_price)+'</div></div><b class="'+(Number(x.unrealized_pl||0)>=0?'up':'down')+'">'+money(x.unrealized_pl)+'</b></div>').join(''):'<div class="list-row"><div><b>No live position</b><div class="secondary">A position appears here after an eligible signal is executed.</div></div></div>';let non=events.filter(e=>String(e.type).includes('no_qualifying_signal')).length,risk=events.find(e=>e.type==='risk_decision'&&e.payload&&e.payload.approved===false);if(events.length){q('#activity').innerHTML=events.slice(0,6).map(e=>'<div class="event"><i class="dot"></i><div><div class="event-title">'+esc(fmtEvent(e.type))+'</div><div class="secondary">'+esc(eventDetail(e))+'</div></div><div class="event-time">'+new Date(String(e.timestamp).endsWith('Z')?e.timestamp:e.timestamp+'Z').toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+'</div></div>').join('')}else q('#activity').innerHTML='<div class="event"><i class="dot"></i><div class="event-title">No live worker events yet</div></div>';q('#workerState').textContent=risk?'Candidate blocked by execution quality':(non?'Scanning: no eligible signal yet':'Live worker active');q('#workerDetail').textContent=risk?'The latest candidate was rejected: '+(risk.payload.reasons||[]).join(', ')+'. No order was sent.':(non?'The validated strategy is scanning its approved universe for a setup that meets trend, pullback, quote freshness, and spread rules.':'The live worker is reconciling account and protection state.')}catch(e){q('#workerState').textContent='Broker snapshot unavailable';q('#workerDetail').textContent='The dashboard will retry without placing or changing any orders.'}}
watch();loadMarket();loadAccount();setInterval(loadMarket,20000);setInterval(loadAccount,10000);
</script></body></html>'''
